<style>
:root{--cyan:#08dcf4;--purple:#762cff;--green:#25df87;--yellow:#ffd43b;--red:#ff6274;--panel:#0c151d;--panel2:#101e28;--border:rgba(139,184,204,.2);--muted:#94a8b6}*{box-sizing:border-box}body{margin:0;min-height:100vh;background:radial-gradient(circle at 82% 0,rgba(8,220,244,.1),transparent 31%),radial-gradient(circle at 8% 22%,rgba(118,44,255,.1),transparent 28%),#050a10;color:#f7f9fb;font-family:Cairo,Arial,sans-serif}button,input,select,textarea{font:inherit}.modular-page{margin-right:245px;padding:26px clamp(16px,2.2vw,36px) 80px}.glass{border:1px solid var(--border);border-radius:24px;background:linear-gradient(135deg,rgba(17,28,38,.97),rgba(7,18,25,.97));box-shadow:0 20px 70px rgba(0,0,0,.25)}.hero,.section{margin-bottom:18px;padding:23px}.hero-top,.actions,.section-head,.inline{display:flex;align-items:center;gap:10px}.hero-top,.section-head{justify-content:space-between}.eyebrow{color:var(--cyan);font-size:11px;font-weight:900;letter-spacing:.08em}.hero h1{margin:5px 0;font-size:clamp(25px,3vw,38px)}.hero p,.muted{color:var(--muted)}.hero p{margin:4px 0}.actions{flex-wrap:wrap}.btn{display:inline-flex;min-height:43px;align-items:center;justify-content:center;gap:7px;padding:9px 14px;border:1px solid var(--border);border-radius:13px;background:#0a1720;color:#eaf7fb;text-decoration:none;cursor:pointer}.btn:hover{border-color:var(--cyan)}.btn-primary{border:0;background:linear-gradient(110deg,var(--cyan),#45a1ff);color:#001014;font-weight:900}.btn-danger{border-color:rgba(255,98,116,.35);color:#ff8795}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-bottom:18px}.stat{padding:20px}.stat small{color:var(--muted)}.stat strong{display:block;margin-top:6px;color:var(--cyan);font-size:30px}.section-head{margin-bottom:18px}.section-head h2{margin:0;font-size:23px}.categories{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.category{overflow:hidden}.category-head{display:flex;align-items:center;gap:14px;padding:16px;border-bottom:1px solid var(--border)}.category-head img{width:82px;height:70px;border-radius:13px;object-fit:cover}.category-copy{min-width:0;flex:1}.category-copy h3{margin:0;font-size:18px}.category-copy small{color:var(--muted)}.service-list{display:grid;gap:9px;padding:13px}.service-row{display:flex;align-items:center;gap:10px;padding:11px;border:1px solid rgba(139,184,204,.14);border-radius:14px;background:rgba(255,255,255,.025)}.service-row img{width:58px;height:50px;border-radius:10px;object-fit:cover}.service-info{min-width:0;flex:1}.service-info b,.service-info small{display:block}.service-info small{color:var(--muted);font-size:10px}.empty{padding:35px 16px;text-align:center;color:var(--muted)}.table-wrap{overflow-x:auto;border:1px solid var(--border);border-radius:17px}table{width:100%;border-collapse:collapse;min-width:900px}th,td{padding:13px;border-bottom:1px solid var(--border);text-align:right;vertical-align:top}th{background:rgba(8,220,244,.06);color:#a9c5d2;font-size:11px}td{font-size:12px}.request-options{display:flex;max-width:380px;flex-wrap:wrap;gap:5px}.chip{padding:4px 8px;border:1px solid var(--border);border-radius:999px;background:#09151d;color:#bed0da;font-size:10px}.status-select{min-height:42px;padding:0 10px;border:1px solid var(--border);border-radius:11px;background:#07121a;color:#fff}.pagination{margin-top:16px}.form-section{margin-bottom:16px;padding:22px}.form-section h2{margin:0 0 17px;font-size:21px}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.field{display:block}.field.full{grid-column:1/-1}.field>span{display:block;margin-bottom:7px;color:#dcebf1;font-size:12px;font-weight:800}.control{width:100%;min-height:52px;padding:0 14px;border:1px solid var(--border);border-radius:13px;outline:0;background:#07131b;color:#fff}.control:focus{border-color:var(--cyan);box-shadow:0 0 0 3px rgba(8,220,244,.08)}textarea.control{min-height:115px;padding-top:12px;resize:vertical}.check{display:flex;align-items:center;gap:8px}.check input{width:19px;height:19px;accent-color:var(--cyan)}.error-box,.success-box{margin-bottom:16px;padding:14px 17px;border-radius:14px}.error-box{border:1px solid rgba(255,98,116,.45);background:rgba(255,98,116,.08);color:#ffd9dd}.success-box{border:1px solid rgba(37,223,135,.4);background:rgba(37,223,135,.08);color:#b9ffdb}.image-preview{width:180px;max-width:100%;height:125px;margin-bottom:10px;border:1px solid var(--border);border-radius:15px;object-fit:cover}.option-groups{display:grid;gap:14px}.option-group{padding:17px;border:1px solid rgba(8,220,244,.24);border-radius:17px;background:rgba(8,220,244,.03)}.group-head,.value-row{display:flex;align-items:center;gap:9px}.group-head{justify-content:space-between;margin-bottom:14px}.group-head strong{color:var(--cyan)}.option-values{display:grid;gap:9px;margin-top:13px}.value-row{padding:10px;border:1px solid var(--border);border-radius:13px;background:#07131b}.value-row .control{min-width:0;flex:1}.icon-btn{display:grid;width:40px;height:40px;flex:0 0 auto;place-items:center;border:1px solid var(--border);border-radius:11px;background:#0a1720;color:#fff;cursor:pointer}.icon-btn.danger{color:var(--red)}.existing-images{display:flex;flex-wrap:wrap;gap:11px}.existing-image{position:relative}.existing-image img{width:150px;height:105px;border-radius:14px;object-fit:cover}.existing-image button{position:absolute;top:6px;inset-inline-end:6px}.sticky-save{position:sticky;z-index:20;bottom:14px;display:flex;justify-content:flex-end;margin-top:18px;padding:11px;border:1px solid rgba(8,220,244,.2);border-radius:18px;background:rgba(4,10,15,.85);backdrop-filter:blur(14px)}
@media(max-width:900px){.modular-page{margin-right:0;padding:14px 12px 105px}.hero,.section,.form-section{padding:17px;border-radius:19px}.hero-top,.section-head{align-items:flex-start;flex-direction:column}.stats{grid-template-columns:repeat(2,minmax(0,1fr))}.categories{grid-template-columns:1fr}.form-grid{grid-template-columns:1fr}.field.full{grid-column:auto}.value-row{align-items:stretch;flex-wrap:wrap}.value-row .control{flex-basis:calc(50% - 8px)}.sticky-save{bottom:86px}.table-wrap{border:0;overflow:visible}table,tbody{display:block;min-width:0}thead{display:none}tr{display:grid;gap:7px;margin-bottom:12px;padding:15px;border:1px solid var(--border);border-radius:16px;background:#08151d}td{display:block;padding:2px;border:0}td:before{content:attr(data-label);display:block;margin-bottom:2px;color:var(--muted);font-size:10px}}
</style>
